import React, { useState, useEffect } from 'react';
import { Canvas, useFrame } from '@react-three/fiber'; // Import useFrame
import { OrbitControls } from '@react-three/drei';
import { OBJLoader } from 'three/examples/jsm/loaders/OBJLoader';
import * as THREE from 'three';

// Use OBJLoader to load the model
const ModelLoader = ({ modelPath }) => {
  const [model, setModel] = useState(null);

  useEffect(() => {
    const loader = new OBJLoader();

    loader.load(
      modelPath, // Path to the OBJ file
      (obj) => {
        setModel(obj); // Set the loaded model
      },
      undefined, // Optional progress callback
      (error) => {
        console.error('Error loading OBJ:', error); // Error handling
      }
    );
  }, [modelPath]);

  // If the model is loaded, return it; otherwise, show a placeholder cube
  return model ? <ModelWithAnimation model={model} /> : <PlaceholderModel />;
};

// ModelWithAnimation component
const ModelWithAnimation = ({ model }) => {
  // Use the useFrame hook to animate the model
  useFrame(() => {
    // Rotate the model on every frame
    if (model) {
      model.rotation.y += 0.01; // Rotate the model around the Y-axis
    }
  });

  return <primitive object={model} />;
};

// Placeholder mesh component
const PlaceholderModel = () => (
  <mesh>
    <boxGeometry args={[1, 1, 1]} />
    <meshStandardMaterial color="gray" />
  </mesh>
);

const App = () => {
  // Path to the model (from the src/stls folder)
  const modelPath = require('./stls/model.obj'); // Import the model from the stls folder

  return (
    <div>
      <h1>3D Model Viewer</h1>
      {/* Canvas is the 3D scene container */}
      <Canvas
        camera={{ position: [0, 0, 5], fov: 75 }} // Initial camera setup
      >
        {/* Lights */}
        <ambientLight intensity={0.5} />
        <spotLight position={[10, 10, 10]} intensity={1} />

        {/* Model loader */}
        <ModelLoader modelPath={modelPath} />

        {/* Orbit controls for camera movement */}
        <OrbitControls />
      </Canvas>
    </div>
  );
};

export default App;
